                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % mod;
            }
        }

        // Precompute powers of 2 mod p
        long[] pow2 = new long[MAX * MAX];
        pow2[0] = 1;
        for (int i = 1; i < pow2.length; i++) {
            pow2[i] = (pow2[i-1] * 2) % mod;
        }

        // DP to compute dp[i][j]: number of ways to place j people in first i computers
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1] * (i - j + 1)) % mod;
            }
        }

        long ans = 0;
        for (int k = 1; k <= m; k++) {
            // Choose k computers out of n
            long ways = C[n][k];
            // Number of ways to assign directions: 2^k
            ways = ways * pow2[k] % mod;
            // Number of ways to assign a_i to these k computers: k!
            long perm = 1;
            for (int i = 1; i <= k; i++) {
                perm = perm * i % mod;
            }
            ways = ways * perm % mod;
            // Number of ways to place remaining m-k people in remaining n-k computers
            long rem = dp[n - k][m - k];
            // Each of the remaining m-k people has 2 choices for direction
            rem = rem * pow2[m - k] % mod;
            ways = ways * rem % mod;
            // Contribution to answer: k * ways
            ans = (ans + (long) k * ways) % mod;
        }

        System.out.println(ans);
    }
