import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    static final int MAX_N = 505;
    static long[][] dp = new long[MAX_N][MAX_N];
    static long[] fact = new long[MAX_N];
    static long[] invFact = new long[MAX_N];
    static long mod;

    static long modPow(long a, long b, long mod) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    static void precomputeFactorials(int n, long mod) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % mod;
        }
        invFact[n] = modPow(fact[n], mod - 2, mod);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % mod;
        }
    }

    static long comb(int n, int k, long mod) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % mod * invFact[n - k] % mod;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        mod = Long.parseLong(st.nextToken());

        precomputeFactorials(n, mod);

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = 0;
            }
        }
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod;
                }
            }
        }

        long ans = 0;
        for (int d = 1; d <= n; d++) {
            long ways = 0;
            for (int k = 1; k <= m; k++) {
                long c = comb(m, k, mod);
                c = c * modPow(2, m - k, mod) % mod;
                c = c * dp[n - d][k - 1] % mod;
                c = c * dp[n - d][m - k] % mod;
                ways = (ways + c) % mod;
            }
            ans = (ans + ways * d % mod) % mod;
        }

        ans = ans * modPow(2, m, mod) % mod;
        System.out.println(ans);
    }
}
