                sum[i][j] = (sum[i][j] + sum[i-1][j] + dp[i-1][j] * (j-1)) % p;
            }
        }

        // Calculate final answer
        long ans = 0;
        for (int j = 1; j <= n; j++) {
            long term = (sum[m][j] * powN[n - j] % p) * C[n][j] % p;
            ans = (ans + term) % p;
        }

