import java.io.*;
import java.util.*;

public class Main {
    static final int MAX = 505;
    static long[][] C = new long[MAX][MAX];
    static long[][] dp = new long[MAX][MAX];
    static long mod;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        mod = Long.parseLong(st.nextToken());

        // Precompute combinations
        for (int i = 0; i < MAX; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % mod;
            }
        }

        // Precompute powers of 2
        long[] pow2 = new long[MAX * MAX];
        pow2[0] = 1;
        for (int i = 1; i < pow2.length; i++) {
            pow2[i] = (pow2[i-1] * 2) % mod;
        }

        // dp[i][j] = number of ways to place j people in i computers
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1] * (2 * i - 1) % mod) % mod;
            }
        }

        long ans = 0;
        for (int k = 1; k <= m; k++) {
            long ways = C[m][k];
            ways = ways * dp[n][k] % mod;
            ways = ways * pow2[k * (m - k)] % mod;
            ways = ways * k % mod;
            ans = (ans + ways) % mod;
        }

        System.out.println(ans);
    }
}
