        int m = fs.nextInt();
        int mod = fs.nextInt();

        long[][] C = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }

        long[][] dp = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = 0;
            }
        }
        dp[0][0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                if (dp[i - 1][j] == 0) continue;
                for (int k = 1; j + k <= n; k++) {
                    long ways = C[n - j - 1][k - 1];
                    ways = ways * dp[i - 1][j] % mod;
                    ways = ways * 2 % mod;
                    dp[i][j + k] = (dp[i][j + k] + ways) % mod;
                }
            }
        }

        long ans = 0;
        for (int j = 0; j <= n; j++) {
            if (dp[m][j] == 0) continue;
            long ways = dp[m][j];
            for (int i = 1; i <= m; i++) {
                long temp = C[j][i];
                temp = temp * C[n - j][m - i] % mod;
                temp = temp * ways % mod;
                temp = temp * i % mod;
                temp = temp * (j - i + 1) % mod;
                ans = (ans + temp) % mod;
            }
        }

        ans = ans * modInverse(2, mod) % mod;
        ans = (ans % mod + mod) % mod;
        System.out.println(ans);
    }

    static long modInverse(long a, long mod) {
        return pow(a, mod - 2, mod);
    }

    static long pow(long a, long b, long mod) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = res * a % mod;
            }
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

