            for (int j = 0; j <= m; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (n - i + 1) % mod * pow2[j - 1] % mod) % mod;
                }
            }
