                for (int k = i-1; k >= 1; k--) {
                    ways[i][j] = (ways[i][j] + ways[k][j-1]) % mod;
                }
            }
        }

        long ans = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
